import { useEffect, useState } from "react";

/**
 * Creates a throttled function that only invokes the provided callback
 * at most once per every `ms` milliseconds.
 * @category utilities
 * @template T - The array of argument types for the callback.
 * @param {(...args: T) => void} cb - The callback function to throttle.
 * @param {number} ms - The number of milliseconds to throttle invocations to.
 * @returns {(...args: T) => void} A new throttled function.
 * @public
 */
export function throttle<T extends any[]>(
  cb: (...args: T) => void,
  ms: number,
): (...args: T) => void {
  let lastTime = 0;

  return (...args: T) => {
    const now = Date.now();
    if (now - lastTime >= ms) {
      cb(...args);
      lastTime = now;
    }
  };
}

/**
 * Custom hook that tracks whether the user is idle based on activity events.
 * @category sensors
 * @param {number} [ms=60000] - The time in milliseconds before the user is considered idle.
 * @returns {boolean} A boolean value indicating if the user is currently idle.
 * @see [Documentation](https://sse-hooks.vercel.app/docs/hooks/use-idle)
 * @public
 */
export function useIdle(ms: number = 1000 * 60): boolean {
  const [idle, setIdle] = useState(false);

  useEffect(() => {
    let timeoutId: number;

    const handleTimeout = () => {
      setIdle(true);
    };

    const handleEvent = throttle(() => {
      setIdle(false);
      window.clearTimeout(timeoutId);
      timeoutId = window.setTimeout(handleTimeout, ms);
    }, 500);

    const handleVisibilityChange = () => {
      if (!document.hidden) {
        handleEvent();
      }
    };

    timeoutId = window.setTimeout(handleTimeout, ms);

    window.addEventListener("mousemove", handleEvent);
    window.addEventListener("mousedown", handleEvent);
    window.addEventListener("resize", handleEvent);
    window.addEventListener("keydown", handleEvent);
    window.addEventListener("touchstart", handleEvent);
    window.addEventListener("wheel", handleEvent);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      window.removeEventListener("mousemove", handleEvent);
      window.removeEventListener("mousedown", handleEvent);
      window.removeEventListener("resize", handleEvent);
      window.removeEventListener("keydown", handleEvent);
      window.removeEventListener("touchstart", handleEvent);
      window.removeEventListener("wheel", handleEvent);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.clearTimeout(timeoutId);
    };
  }, [ms]);

  return idle;
}

